<?php
namespace Core;require_once __DIR__.'/Guard.php';ml_guard_shield(__FILE__);class LinkChecker{public static function check($a,$b=8){$a=trim($a);if($a===''||!preg_match('#^https?://#i',$a)){return['ok'=>false,'code'=>0,'msg'=>'无效地址'];}$c=self::request($a,true,$b);if($c['err']!==''||in_array($c['code'],[0,403,405,501],true)){$c=self::request($a,false,$b);}if($c['err']!==''){return['ok'=>false,'code'=>0,'msg'=>$c['err']];}$d=$c['code']>=200&&$c['code']<400;return['ok'=>$d,'code'=>$c['code'],'msg'=>$d?'':'HTTP '.$c['code']];}private static function request($a,$b,$c){$d=curl_init($a);$e=[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>$c,CURLOPT_CONNECTTIMEOUT=>6,CURLOPT_FOLLOWLOCATION=>true,CURLOPT_MAXREDIRS=>5,CURLOPT_NOBODY=>$b,CURLOPT_USERAGENT=>'Mozilla/5.0 (compatible; MediaLibLinkCheck/1.0)',CURLOPT_SSL_VERIFYPEER=>false,CURLOPT_SSL_VERIFYHOST=>0,CURLOPT_HTTPHEADER=>['Accept: */*','Cache-Control: no-cache'],];if(!$b){$e[CURLOPT_RANGE]='0-2047';}curl_setopt_array($d,$e);curl_exec($d);$f=(int)curl_getinfo($d,CURLINFO_HTTP_CODE);$g=curl_error($d);curl_close($d);return['code'=>$f,'err'=>$g];}}